def ship_payload(cls):
    """One ship's data, or None when the class is unknown. Case-insensitive."""
    global _SHIPS
    if not cls:
        return None
    if _SHIPS is None:
        _SHIPS = {k.lower(): (k, v) for k, v in json.loads(SHIPS_JSON).items()}
    hit = _SHIPS.get(str(cls).lower())
    if not hit:
        return None
    return dict(hit[1], **{'class': hit[0]})
